import re
from collections import Counter


def clean_text(text):
    without_symbols = re.sub(r"[^A-Za-z\s]", "", text)
    return re.sub(r"\s+", " ", without_symbols).strip()


def most_frequent_words(text, n):
    cleaned = clean_text(text)
    counts = Counter(cleaned.split())
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return [(count, word) for word, count in ranked[:n]]
